-- B3 SORTS — Étape 2 : remplissage de description_courte (mode « Fiche »)
-- Convention prières (bornes fléchées 1 → N, clauses Niv. X, pas de redite portée/durée/zone).
-- description (verbatim « Manuel ») reste INTACTE. UPDATE idempotents gardés par nom + cercle.
-- 136 lignes (135 sorts distincts ; « Poigne de fer » est cross-listée Combat + Terre).

ALTER TABLE public.sorts ADD COLUMN IF NOT EXISTS description_courte text;

UPDATE public.sorts SET description_courte = 'Bouclier absorbant des dégâts de foudre = moitié du niveau (arrondi sup.).' WHERE nom = 'Bouclier de Vent' AND cercle = 'Air';
UPDATE public.sorts SET description_courte = 'Repousse la cible au sol sur (moitié du niveau + 3 pieds).' WHERE nom = 'Bourrasque' AND cercle = 'Air';
UPDATE public.sorts SET description_courte = 'Bloque 1 → 6 projectiles physiques selon le niveau ; au Niv. 20, tous les projectiles.' WHERE nom = 'Globe d''Air' AND cercle = 'Air';
UPDATE public.sorts SET description_courte = 'Rend inconscientes les cibles de la zone 5 min ; réveil seulement par des dégâts ou une dissipation.' WHERE nom = 'Nuage de Mort' AND cercle = 'Air';
UPDATE public.sorts SET description_courte = 'Inflige 1 → 8 dégâts de foudre selon le niveau.' WHERE nom = 'Rayon Électrique' AND cercle = 'Air';
UPDATE public.sorts SET description_courte = 'Enchante des armes (1 par cible) : « Repoussement 5 pieds » 1 → 5 fois selon le niveau ; durée +1 min/niveau.' WHERE nom = 'Tornade Martiale' AND cercle = 'Air';
UPDATE public.sorts SET description_courte = 'Étouffe la cible : à terre, incapable d''attaquer, d''incanter ou d''utiliser des compétences (déplacement lent possible).' WHERE nom = 'Asphyxie' AND cercle = 'Air';
UPDATE public.sorts SET description_courte = 'Rend les cibles intangibles (brume) : atteignables seulement par la magie pure ou des armes magiques, mais incapables d''attaquer, se défendre ou lancer des sorts.' WHERE nom = 'Forme de Brume' AND cercle = 'Air';
UPDATE public.sorts SET description_courte = 'Inflige 3 → 7 dégâts de foudre à toute la zone (alliés compris) selon le niveau. Niv. 20 : les alliés ne sont plus touchés.' WHERE nom = 'Tempête de Foudre' AND cercle = 'Air';
UPDATE public.sorts SET description_courte = 'Inflige au toucher 4 → 10 dégâts de foudre selon le niveau ; à haut niveau, peut frapper 2 cibles (dégâts réduits).' WHERE nom = 'Toucher Foudroyant' AND cercle = 'Air';
UPDATE public.sorts SET description_courte = 'Donne aux cibles un trait racial d''une race au choix (costume requis). Niv. 11 : 2 traits, jetable sur cible non consentante. Niv. 20 : changement de race permanent (si consentant).' WHERE nom = 'Altération du Corps' AND cercle = 'Altération';
UPDATE public.sorts SET description_courte = 'Rend des objets intangibles, donc insaisissables (objet porté : niveau du sort vs porteur ; armure perd ses points). Niv. 11 : objets magiques niv. ≤ 3. Niv. 20 : artéfacts.' WHERE nom = 'État Instable' AND cercle = 'Altération';
UPDATE public.sorts SET description_courte = 'Rend un objet si fragile qu''il se brise au moindre dégât. Matériaux selon le niveau : verre/gemmes (1), bois (6), métal (10). Niv. 20 : tout objet sauf artéfact.' WHERE nom = 'Fragilité' AND cercle = 'Altération';
UPDATE public.sorts SET description_courte = 'Rend les cibles intangibles (fantôme) : atteignables seulement par la magie pure ou des armes magiques, incapables d''attaquer, se défendre ou lancer des sorts sur le tangible.' WHERE nom = 'Intangibilité' AND cercle = 'Altération';
UPDATE public.sorts SET description_courte = 'Ralentit la cible à 50 % : ses coups n''infligent plus de dégâts, déplacement en marche lente, voix incompréhensible.' WHERE nom = 'Lenteur' AND cercle = 'Altération';
UPDATE public.sorts SET description_courte = 'L''objet ciblé ne peut plus être soulevé (objet porté : niveau du sort vs porteur). Niv. 11 : 2 objets. Niv. 20 : le lanceur n''est pas affecté.' WHERE nom = 'Augmentation du poids' AND cercle = 'Altération';
UPDATE public.sorts SET description_courte = 'La cible se comporte comme un animal choisi (comportement seul) : ne peut utiliser ni compétence ni équipement. Garde le souvenir à la fin.' WHERE nom = 'Demi-morphisme' AND cercle = 'Altération';
UPDATE public.sorts SET description_courte = 'Rend des objets indestructibles : protège contre la destruction et la Fragilité, sauf face à un sort de niveau supérieur.' WHERE nom = 'Indestructibilité' AND cercle = 'Altération';
UPDATE public.sorts SET description_courte = 'Paralyse les cibles : immobiles et muettes (vue et ouïe intactes). Dissipé si la cible subit des dégâts.' WHERE nom = 'Paralysie' AND cercle = 'Altération';
UPDATE public.sorts SET description_courte = 'Vieillit les cibles : trop affaiblies pour se battre ou lancer des sorts, déplacements lents. Niv. 20 : vieillissement permanent et irréversible (si consentant).' WHERE nom = 'Vieillissement' AND cercle = 'Altération';
UPDATE public.sorts SET description_courte = 'Rend les cibles amicales envers le lanceur : elles cessent de l''attaquer (sans risquer leur vie pour lui). Fin s''il se montre hostile.' WHERE nom = 'Amitié' AND cercle = 'Charmes';
UPDATE public.sorts SET description_courte = 'Rend les cibles hostiles envers le lanceur : elles se mettent à le détester (sans aller jusqu''à le tuer).' WHERE nom = 'Antipathie' AND cercle = 'Charmes';
UPDATE public.sorts SET description_courte = 'Les cibles cherchent par tous les moyens à s''emparer d''un objet désigné et à le garder. Fin si la cible tombe inconsciente.' WHERE nom = 'Avidité' AND cercle = 'Charmes';
UPDATE public.sorts SET description_courte = 'Force les cibles à fixer leur attention sur le lanceur tant qu''il parle ou se donne en spectacle. Fin pour une cible blessée ou bousculée.' WHERE nom = 'Discours captivant' AND cercle = 'Charmes';
UPDATE public.sorts SET description_courte = 'Force la cible à obéir à un ordre : plus le niveau monte, plus l''ordre est long et contraignant (5 → 20 mots) ; à haut niveau, elle n''en garde aucun souvenir.' WHERE nom = 'Domination' AND cercle = 'Charmes';
UPDATE public.sorts SET description_courte = 'Abrutit la cible : phrases de 5 mots max, ne peut ni lancer de sorts/prières ni utiliser de compétences (réflexes de défense conservés).' WHERE nom = 'Esprit du Simplet' AND cercle = 'Charmes';
UPDATE public.sorts SET description_courte = 'Prise d''un fou rire : la cible ne peut ni attaquer ni lancer de sort et peine à se défendre. Niv. 11 : également aveuglée.' WHERE nom = 'Fou Rire Incessant' AND cercle = 'Charmes';
UPDATE public.sorts SET description_courte = 'Soumet une créature non humanoïde : elle obéit au lanceur selon ses capacités, sans jamais se mettre en danger de mort.' WHERE nom = 'Envoûtement de Créature' AND cercle = 'Charmes';
UPDATE public.sorts SET description_courte = 'La cible est incapable de dire la vérité (à l''oral comme à l''écrit) et résiste aux effets de vérité de niveau inférieur.' WHERE nom = 'Mensonge' AND cercle = 'Charmes';
UPDATE public.sorts SET description_courte = 'Efface les souvenirs récents de la cible (2 → 30 min selon le niveau). Permanent, indétectable ; une seule fois par événement.' WHERE nom = 'Oubli' AND cercle = 'Charmes';
UPDATE public.sorts SET description_courte = 'Plonge les cibles dans un sommeil profond ; réveil au moindre dégât ou contact. Niv. 11 : peut être déplacée/fouillée sans se réveiller.' WHERE nom = 'Sommeil' AND cercle = 'Charmes';
UPDATE public.sorts SET description_courte = 'Confère 1 → 5 points d''armure temporaires selon le niveau (non récupérables, cumulables avec une armure physique).' WHERE nom = 'Armure' AND cercle = 'Combat';
UPDATE public.sorts SET description_courte = 'Permet au lanceur de combattre normalement même aveuglé (il garde les yeux ouverts).' WHERE nom = 'Combat Aveugle' AND cercle = 'Combat';
UPDATE public.sorts SET description_courte = 'Supprime la douleur (les dégâts s''appliquent quand même). Niv. 6 : immunise contre Torture. Niv. 11 : résiste aux sorts de douleur de niveau inférieur.' WHERE nom = 'Insensibilité à la douleur' AND cercle = 'Combat';
UPDATE public.sorts SET description_courte = 'Effet de peur : les cibles ne peuvent pas attaquer le lanceur et doivent fuir hors de sa vue (elles peuvent encore se défendre).' WHERE nom = 'Présence intimidante' AND cercle = 'Combat';
UPDATE public.sorts SET description_courte = 'Force la cible à tenter de blesser le lanceur ; l''effet cesse dès qu''elle l''a fait saigner.' WHERE nom = 'Provocation' AND cercle = 'Combat';
UPDATE public.sorts SET description_courte = 'Immunise contre les attaques sournoises selon le niveau (Égorgement/Assommement → Brise-Cou → Backstab) et réduit de moitié les dégâts de pièges.' WHERE nom = 'Sens aiguisé' AND cercle = 'Combat';
UPDATE public.sorts SET description_courte = 'Enchante des armes (1 par cible) : dégâts magiques (Niv. 6), indestructible (10), insensible aux sorts (15). Niv. 20 : toutes les armes à 10 pieds frappent magique.' WHERE nom = 'Arme Magique' AND cercle = 'Combat';
UPDATE public.sorts SET description_courte = 'Inflige 1 → 5 dégâts de magie pure selon le niveau. Lançable en plein combat sans être déconcentré par les coups reçus.' WHERE nom = 'Lame Dimensionnelle' AND cercle = 'Combat';
UPDATE public.sorts SET description_courte = 'Permet de porter des armes à deux mains sans en avoir la compétence. Niv. 11 : la cible ne peut plus être désarmée.' WHERE nom = 'Poigne de fer' AND cercle = 'Combat';
UPDATE public.sorts SET description_courte = 'Confère un bouclier (1 par cible) annulant 1 → 3 prochains sorts à dégâts selon le niveau.' WHERE nom = 'Bouclier Mystique' AND cercle = 'Combat';
UPDATE public.sorts SET description_courte = 'Communique avec un esprit choisi : il discute pleinement et ne peut mentir (efficacité selon le niveau). Nécessite un animateur.' WHERE nom = 'Contact avec les Esprits' AND cercle = 'Divination';
UPDATE public.sorts SET description_courte = 'Confirme la présence ou l''absence d''une aura magique (sans sa nature). Objet porté : niveau du sort ≥ porteur. Repère aussi les fausses auras.' WHERE nom = 'Détection de la magie' AND cercle = 'Divination';
UPDATE public.sorts SET description_courte = 'Détecte et nomme poisons, maladies et parasites (sans leurs effets ni traitement) ; portée croissante du mineur au majeur selon le niveau.' WHERE nom = 'Détection des Toxines' AND cercle = 'Divination';
UPDATE public.sorts SET description_courte = 'Permet de comprendre et parler les langues inconnues pour la durée du sort.' WHERE nom = 'Don des Langues' AND cercle = 'Divination';
UPDATE public.sorts SET description_courte = 'Révèle si la cible peut lancer des sorts et l''origine de son pouvoir (magique/divin). Niv. 11 : ses écoles/domaines. Niv. 20 : son niveau de maîtrise.' WHERE nom = 'Sensibilité des Arcanes' AND cercle = 'Divination';
UPDATE public.sorts SET description_courte = 'Immunise les cibles contre les sorts d''Illusion de niveau ≤ au sort (annoncer « Résiste »).' WHERE nom = 'Vision Lucide' AND cercle = 'Divination';
UPDATE public.sorts SET description_courte = 'Pose des questions (oui/non/indécis) à une force supérieure ; nombre = moitié du niveau (arrondi sup.). Nécessite un animateur.' WHERE nom = 'Augure' AND cercle = 'Divination';
UPDATE public.sorts SET description_courte = 'Détecte les assemblages runiques sur la cible (corps puis équipement selon le niveau). Niv. 11 : les identifie tous. Niv. 20 : les bloque 5 min.' WHERE nom = 'Détection runique' AND cercle = 'Divination';
UPDATE public.sorts SET description_courte = 'Identifie les écoles et domaines des sorts actuellement actifs sur la cible (sans leurs effets, durée ni niveau).' WHERE nom = 'Vision de la magie' AND cercle = 'Divination';
UPDATE public.sorts SET description_courte = 'Détecte et identifie une malédiction (puissance + effets généraux). Portée mineure → majeure selon le niveau ; Niv. 20 : aussi son origine. Ne peut pas la lever.' WHERE nom = 'Connaissance des malédictions' AND cercle = 'Divination';
UPDATE public.sorts SET description_courte = 'Les cibles agissent comme exposées à -40 °C : impossible de se concentrer pour lancer des sorts ou utiliser des compétences.' WHERE nom = 'Abaissement de Température' AND cercle = 'Eau';
UPDATE public.sorts SET description_courte = 'Bouclier absorbant des dégâts de glace = moitié du niveau (arrondi sup.).' WHERE nom = 'Bouclier de Glace' AND cercle = 'Eau';
UPDATE public.sorts SET description_courte = 'Immunise contre les nouveaux poisons (mineurs → majeurs selon le niveau). Niv. 20 : survit au poison mortel (comateux à 0 PV au lieu de mourir).' WHERE nom = 'Immunité au Poison' AND cercle = 'Eau';
UPDATE public.sorts SET description_courte = 'Inflige 1 → 8 dégâts de glace selon le niveau.' WHERE nom = 'Projectile de glace' AND cercle = 'Eau';
UPDATE public.sorts SET description_courte = 'Purifie un liquide non consommé de toute maladie, potion ou poison (mineur → majeur selon le niveau).' WHERE nom = 'Purification des Liquides' AND cercle = 'Eau';
UPDATE public.sorts SET description_courte = 'Gèle des objets métalliques : impossibles à tenir (objet porté : niveau du sort vs porteur). Niv. 11 : si l''objet ne peut être retiré, 1 dégât de glace puis 1/min.' WHERE nom = 'Froid Glacial' AND cercle = 'Eau';
UPDATE public.sorts SET description_courte = 'Transforme les cibles en statue de glace : immobiles et muettes, mais insensibles aux dégâts (sens conservés). N''est pas de la pétrification.' WHERE nom = 'Iceberg' AND cercle = 'Eau';
UPDATE public.sorts SET description_courte = 'La cible se noie : à terre, incapable d''attaquer, d''incanter ou d''utiliser des compétences (déplacement lent possible).' WHERE nom = 'Noyade' AND cercle = 'Eau';
UPDATE public.sorts SET description_courte = 'Rouille des objets métalliques : l''armure perd 1 → 4 combats selon le niveau et les armes deviennent fragiles. Niv. 20 : affecte aussi les objets magiques (sauf artéfacts).' WHERE nom = 'Rouille' AND cercle = 'Eau';
UPDATE public.sorts SET description_courte = 'Inflige au toucher 4 → 10 dégâts de glace selon le niveau ; à haut niveau, peut frapper 2 cibles (dégâts réduits).' WHERE nom = 'Toucher Glacial' AND cercle = 'Eau';
UPDATE public.sorts SET description_courte = 'Armure de givre : points d''armure = moitié du niveau (arrondi sup.), sans armure physique ; vulnérable au feu (+1 dégât). Niv. 15 : riposte 2 dégâts de glace au corps à corps.' WHERE nom = 'Armure Givre' AND cercle = 'Eau';
UPDATE public.sorts SET description_courte = 'Les cibles sont accablées par la soif et doivent chercher de l''eau en priorité (elles peuvent encore se défendre).' WHERE nom = 'Assoiffé' AND cercle = 'Feu';
UPDATE public.sorts SET description_courte = 'Bouclier absorbant des dégâts de feu = moitié du niveau (arrondi sup.).' WHERE nom = 'Bouclier de Feu' AND cercle = 'Feu';
UPDATE public.sorts SET description_courte = 'Inflige 1 → 8 dégâts de feu selon le niveau.' WHERE nom = 'Jet de flammes' AND cercle = 'Feu';
UPDATE public.sorts SET description_courte = 'Génère une lumière magique (lampe torche en jeu) que certaines créatures de l''ombre fuient. Interdit d''aveugler quelqu''un avec.' WHERE nom = 'Lumière' AND cercle = 'Feu';
UPDATE public.sorts SET description_courte = 'Les cibles agissent comme exposées à 60 °C : impossible de se concentrer pour lancer des sorts ou des prières.' WHERE nom = 'Réchauffement de Température' AND cercle = 'Feu';
UPDATE public.sorts SET description_courte = 'Si le lanceur tombe à 0 PV, son corps explose : 2 → 5 dégâts de feu selon le niveau, dans un rayon croissant (5 → 20 pieds). Une seule fois ; le lanceur est épargné.' WHERE nom = 'Brasier Vengeur' AND cercle = 'Feu';
UPDATE public.sorts SET description_courte = 'Chauffe à blanc des objets métalliques : impossibles à tenir (objet porté : niveau du sort vs porteur). Niv. 11 : si l''objet ne peut être retiré, dégâts récurrents (1/min).' WHERE nom = 'Réchauffement du Métal' AND cercle = 'Feu';
UPDATE public.sorts SET description_courte = 'Aura de flammes qui riposte 1 → 3 dégâts de feu (selon le niveau) à chaque attaque de mêlée ou au toucher. Sans effet sur les attaques à distance.' WHERE nom = 'Retour de flamme' AND cercle = 'Feu';
UPDATE public.sorts SET description_courte = 'Inflige au toucher 5 → 10 dégâts de feu selon le niveau ; à haut niveau, peut frapper 2 cibles (dégâts réduits).' WHERE nom = 'Toucher de Braise' AND cercle = 'Feu';
UPDATE public.sorts SET description_courte = 'Enflamme la cible : elle doit s''éteindre aussitôt, sinon elle perd 50 % de ses PV+PA totaux. Une fois par combat.' WHERE nom = 'Brasero' AND cercle = 'Feu';
UPDATE public.sorts SET description_courte = 'Donne à des objets une fausse aura magique au choix (niveau 1 → 4 selon le niveau). Sur un objet déjà magique : le sort doit dépasser son niveau.' WHERE nom = 'Aura magique' AND cercle = 'Illusion';
UPDATE public.sorts SET description_courte = 'Altère les rêves prémonitoires : la compétence « Rêves » renvoie une vision choisie par le lanceur.' WHERE nom = 'Fausses visions' AND cercle = 'Illusion';
UPDATE public.sorts SET description_courte = 'Fait percevoir un bâton comme un serpent venimeux (illusion totale) : effet de peur émanant du bâton.' WHERE nom = 'L''Esprit du Serpent' AND cercle = 'Illusion';
UPDATE public.sorts SET description_courte = 'Modifie l''apparence de la cible pour ne pas être reconnue (sans imiter précisément quelqu''un). Maquillage/accessoires requis en jeu.' WHERE nom = 'Modification d''Apparence' AND cercle = 'Illusion';
UPDATE public.sorts SET description_courte = 'Les cibles surestiment la fortune du lanceur : chaque écu qu''il présente en vaut trois à leurs yeux.' WHERE nom = 'Or des Fous' AND cercle = 'Illusion';
UPDATE public.sorts SET description_courte = 'Les cibles voient tout le monde comme un ennemi et attaquent. Stoppé par un sort de calme supérieur ou si la cible tombe inconsciente.' WHERE nom = 'Rageur Fou' AND cercle = 'Illusion';
UPDATE public.sorts SET description_courte = 'Fait paraître les cibles vivantes (signes vitaux simulés). Trompe Diagnostic 1 (Niv. 6), 2 (11), 3 (20).' WHERE nom = 'Simulacre de vie' AND cercle = 'Illusion';
UPDATE public.sorts SET description_courte = 'Masque l''aura magique d''objets : une détection de niveau inférieur n''y voit aucune magie. Niv. 20 : cache aussi les artéfacts.' WHERE nom = 'Aura indétectable' AND cercle = 'Illusion';
UPDATE public.sorts SET description_courte = 'Permet de remplacer 1 → 5 mots de pouvoir (selon le niveau) par des mots ordinaires dans ses formules de mage.' WHERE nom = 'Incantation Fourbe' AND cercle = 'Illusion';
UPDATE public.sorts SET description_courte = 'Effet de peur : les cibles ne peuvent pas attaquer la source et doivent fuir hors de sa vue (elles peuvent encore se défendre).' WHERE nom = 'Vision Terrifiante' AND cercle = 'Illusion';
UPDATE public.sorts SET description_courte = 'Confronte la cible à sa pire peur : inconsciente 1 min si elle ne résiste pas ; si son niveau < moitié du sort, elle tombe comateuse.' WHERE nom = 'Assassin Imaginaire' AND cercle = 'Illusion';
UPDATE public.sorts SET description_courte = 'Bouclier absorbant des dégâts d''énergie négative = moitié du niveau (arrondi sup.).' WHERE nom = 'Bouclier contre l''Énergie négative' AND cercle = 'Magie Noire';
UPDATE public.sorts SET description_courte = 'Rend les cibles aveugles pour la durée du sort.' WHERE nom = 'Cécité' AND cercle = 'Magie Noire';
UPDATE public.sorts SET description_courte = 'Rend les cibles muettes pour la durée du sort.' WHERE nom = 'Perte de la Parole' AND cercle = 'Magie Noire';
UPDATE public.sorts SET description_courte = 'Inflige 1 → 8 dégâts d''énergie négative selon le niveau.' WHERE nom = 'Rayon d''Énergie Négative' AND cercle = 'Magie Noire';
UPDATE public.sorts SET description_courte = 'La cible se tord de douleur : incapable d''attaquer ou de lancer un sort, et peine à se défendre.' WHERE nom = 'Souffrance' AND cercle = 'Magie Noire';
UPDATE public.sorts SET description_courte = 'La cible perd des points de spiritualité égaux au niveau du sort.' WHERE nom = 'Brûlure Spirituelle' AND cercle = 'Magie Noire';
UPDATE public.sorts SET description_courte = 'La cible passe la nuit en cauchemars : aucun PV ni point de spiritualité récupéré au réveil.' WHERE nom = 'Cauchemar' AND cercle = 'Magie Noire';
UPDATE public.sorts SET description_courte = 'Réduit les PV de la cible à 2 pour la durée. Niv. 11 : plus d''arme à deux mains. Niv. 20 : incapable de combattre (armes ou sorts).' WHERE nom = 'Faiblesse' AND cercle = 'Magie Noire';
UPDATE public.sorts SET description_courte = 'État pestiféré : PV plafonnés à 2 jusqu''à guérison (par une guérison des maladies de niveau supérieur). Niv. 20 : contagieux au toucher.' WHERE nom = 'Pestilence' AND cercle = 'Magie Noire';
UPDATE public.sorts SET description_courte = 'État Saignement : -1 PV/min, que les soins n''arrêtent pas ; ne descend jamais la cible sous 1 PV. Levé par l''anti-magie.' WHERE nom = 'Saignée à blanc' AND cercle = 'Magie Noire';
UPDATE public.sorts SET description_courte = 'Chaque sort lancé par la cible coûte 1 → 4 points de spiritualité supplémentaires selon le niveau.' WHERE nom = 'Saignée Mystique' AND cercle = 'Magie Noire';
UPDATE public.sorts SET description_courte = 'Crée une zone d''obscurité totale : quiconque y entre est aveuglé tant qu''il y reste.' WHERE nom = 'Ténèbres' AND cercle = 'Magie Noire';
UPDATE public.sorts SET description_courte = 'Pose une question au Néant qui répond toujours vrai ; en échange, il faut répondre à la sienne avec vérité, sous peine de malédiction. Niv. 20 : 2 questions (et 2 risques).' WHERE nom = 'L''Entente du Néant' AND cercle = 'Magie Noire';
UPDATE public.sorts SET description_courte = 'Crée une zone où tout sort de niveau inférieur, hors magie noire, n''a aucun effet.' WHERE nom = 'Oraison Funeste' AND cercle = 'Magie Noire';
UPDATE public.sorts SET description_courte = 'Confère des points d''armure = moitié du niveau (arrondi sup.) ; sans effet si la cible porte une armure physique.' WHERE nom = 'Bouclier d''Énergie Spirituelle' AND cercle = 'Magie Pure';
UPDATE public.sorts SET description_courte = 'Bouclier absorbant des dégâts de magie pure = moitié du niveau (arrondi sup.). Inefficace contre le drain de vie et l''énergie négative.' WHERE nom = 'Bouclier Magique' AND cercle = 'Magie Pure';
UPDATE public.sorts SET description_courte = 'Emprisonne dans une bulle infranchissable les créatures présentes ; rien n''entre ni ne sort. Percée (et finie) par un niveau supérieur.' WHERE nom = 'Bulle d''emprisonnement' AND cercle = 'Magie Pure';
UPDATE public.sorts SET description_courte = 'Renvoie à son lanceur un sort ou une prière de niveau inférieur visant la cible.' WHERE nom = 'Miroir' AND cercle = 'Magie Pure';
UPDATE public.sorts SET description_courte = 'Inflige 1 → 8 dégâts magiques selon le niveau (peut toucher les intangibles).' WHERE nom = 'Projectile Magique' AND cercle = 'Magie Pure';
UPDATE public.sorts SET description_courte = 'Zone d''anti-magie : annule tout sort de niveau inférieur qui la traverse et neutralise les objets magiques (niveau 1 → 3 selon le niveau).' WHERE nom = 'Coquille d''anti-magie' AND cercle = 'Magie Pure';
UPDATE public.sorts SET description_courte = 'Dissipe sur les cibles les effets magiques (sorts, potions) de niveau inférieur. Sans effet sur les objets magiques.' WHERE nom = 'Dissipation de la magie' AND cercle = 'Magie Pure';
UPDATE public.sorts SET description_courte = 'Inflige au toucher 4 → 10 dégâts magiques selon le niveau (touche les intangibles) ; à haut niveau, peut frapper 2 cibles.' WHERE nom = 'Explosion arcanique' AND cercle = 'Magie Pure';
UPDATE public.sorts SET description_courte = 'Transfère à une cible vivante 2 → 10 points de spiritualité selon le niveau (sans dépasser son maximum).' WHERE nom = 'Inspiration spirituel' AND cercle = 'Magie Pure';
UPDATE public.sorts SET description_courte = 'Dissipe le premier sort visant le lanceur et lui rend 1 point de spiritualité (pas les attaques physiques). Niv. 20 : 1 spiritualité ou 1 PV au choix.' WHERE nom = 'Absorption Magique' AND cercle = 'Magie Pure';
UPDATE public.sorts SET description_courte = 'Relève des cibles mortes ou comateuses en morts-vivants sous contrôle du lanceur (type ↑ avec le niveau : zombi → spectre). Comateux : se réveille après 1 min sans souvenir.' WHERE nom = 'Animation des morts' AND cercle = 'Nécromancie';
UPDATE public.sorts SET description_courte = 'Bouclier annulant des dégâts de vol de vie = moitié du niveau (arrondi sup.).' WHERE nom = 'Bouclier Contre la Mort' AND cercle = 'Nécromancie';
UPDATE public.sorts SET description_courte = 'Interroge un cadavre (s''il a sa tête) : il répond à voix haute, 1 → 5 questions selon le niveau. Pas en combat.' WHERE nom = 'Communication avec les Cadavres' AND cercle = 'Nécromancie';
UPDATE public.sorts SET description_courte = 'Inflige aux morts-vivants des dégâts magiques égaux au niveau du sort.' WHERE nom = 'Destruction des Morts-Vivants' AND cercle = 'Nécromancie';
UPDATE public.sorts SET description_courte = 'Fait paraître les cibles mortes (signes vitaux absents) ; toute action visible rompt l''effet. Trompe Diagnostic 1 (Niv. 6), 2 (11), 3 (20).' WHERE nom = 'Masque Funèbre' AND cercle = 'Nécromancie';
UPDATE public.sorts SET description_courte = 'Rend tangibles les cibles intangibles et les empêche de le redevenir pour la durée du sort.' WHERE nom = 'Pieu Spirituel' AND cercle = 'Nécromancie';
UPDATE public.sorts SET description_courte = 'Prend le contrôle de morts-vivants : ils obéissent à la lettre, même au péril de leur mort. Reprendre un contrôle existant exige un niveau supérieur.' WHERE nom = 'Contrôle des morts-vivants' AND cercle = 'Nécromancie';
UPDATE public.sorts SET description_courte = 'Inflige 1 → 4 dégâts selon le niveau et soigne le lanceur d''autant (jamais au-delà du max). Niv. 20 : peut transférer ses PV à un allié consentant à 5 pieds.' WHERE nom = 'Drain de vie' AND cercle = 'Nécromancie';
UPDATE public.sorts SET description_courte = 'Les morts-vivants de niveau inférieur n''attaquent plus les cibles (ils peuvent seulement les écarter du passage).' WHERE nom = 'Protection Contre les Morts-Vivants' AND cercle = 'Nécromancie';
UPDATE public.sorts SET description_courte = 'Emprisonne l''âme d''un mort dans une pierre d''âme (niveau du sort ≥ celui du personnage). Briser la pierre libère l''âme.' WHERE nom = 'Capture d''Âmes' AND cercle = 'Nécromancie';
UPDATE public.sorts SET description_courte = 'Les cibles résistent aux pièges avec le niveau du sort au lieu du leur.' WHERE nom = 'Alerte du Danger' AND cercle = 'Protection';
UPDATE public.sorts SET description_courte = 'Immunise contre l''enchevêtrement, la paralysie, la pétrification et la maladresse de niveau inférieur (n''annule pas les effets déjà actifs).' WHERE nom = 'Liberté de Mouvement' AND cercle = 'Protection';
UPDATE public.sorts SET description_courte = 'Immunise contre les effets de paralysie de niveau ≤ au sort (la pétrification est distincte).' WHERE nom = 'Protection contre la Paralysie' AND cercle = 'Protection';
UPDATE public.sorts SET description_courte = 'Encaisse 1 → 5 coups d''armes non magiques selon le niveau sans subir de dégâts (une attaque sournoise consomme toutes les charges restantes).' WHERE nom = 'Protection contre les Armes Conventionnelles' AND cercle = 'Protection';
UPDATE public.sorts SET description_courte = 'Résiste à l''Hypnose (niv. 1 → 3 selon le niveau) : la cible peut mentir ou se taire face à l''hypnotiseur.' WHERE nom = 'Esprit impénétrable' AND cercle = 'Protection';
UPDATE public.sorts SET description_courte = 'Le lanceur encaisse à la place de la cible les dégâts qui lui seraient infligés, tant qu''il la regarde.' WHERE nom = 'Gardien Cabalistique' AND cercle = 'Protection';
UPDATE public.sorts SET description_courte = 'Bloque des dégâts d''énergie négative et de drain de vie = moitié du niveau (arrondi sup.).' WHERE nom = 'Protection contre les Effets Négatifs' AND cercle = 'Protection';
UPDATE public.sorts SET description_courte = 'Empêche les personnages de niveau inférieur d''approcher à moins de 10 pieds (ne bloque ni sorts ni attaques à distance).' WHERE nom = 'Répulsion' AND cercle = 'Protection';
UPDATE public.sorts SET description_courte = 'Tout coup de grâce contre la cible doit être de niveau supérieur au sort.' WHERE nom = 'Lien avec le monde vivant' AND cercle = 'Protection';
UPDATE public.sorts SET description_courte = 'Bouclier absorbant des dégâts d''acide = moitié du niveau (arrondi sup.).' WHERE nom = 'Bouclier de Terre' AND cercle = 'Terre';
UPDATE public.sorts SET description_courte = 'Emprisonne les cibles dans la terre (immobilisées) ; elles peuvent encore attaquer et lancer des sorts, mais pas se déplacer.' WHERE nom = 'Emprisonnement dans la Terre' AND cercle = 'Terre';
UPDATE public.sorts SET description_courte = 'Encaisse 1 → 5 coups d''armes non magiques selon le niveau sans subir de dégâts ; bloque aussi la pétrification de niveau inférieur.' WHERE nom = 'Peau de Pierre' AND cercle = 'Terre';
UPDATE public.sorts SET description_courte = 'Pétrifie la cible : immobile et muette, mais insensible aux blessures (sens conservés). Sert aussi à dépétrifier (niveau supérieur requis).' WHERE nom = 'Pétrification/Dépétrification' AND cercle = 'Terre';
UPDATE public.sorts SET description_courte = 'Inflige 1 → 8 dégâts d''acide selon le niveau.' WHERE nom = 'Rayon d''Acide' AND cercle = 'Terre';
UPDATE public.sorts SET description_courte = 'Fait tomber au sol les personnages touchés (le lanceur est épargné). Niv. 11 : 1 dégât ; Niv. 20 : 2 dégâts à tous.' WHERE nom = 'Tremblement de Terre' AND cercle = 'Terre';
UPDATE public.sorts SET description_courte = 'Permet de porter des armes à deux mains sans en avoir la compétence. Niv. 11 : la cible ne peut plus être désarmée.' WHERE nom = 'Poigne de fer' AND cercle = 'Terre';
UPDATE public.sorts SET description_courte = 'Si la cible tombe à 0 PV (en extérieur), elle régénère au sol : +1 PV/min pendant 5 min et reprend conscience plus vite. Réactivable tant que le sort dure.' WHERE nom = 'Sang de la Terre' AND cercle = 'Terre';
UPDATE public.sorts SET description_courte = 'Inflige au toucher 4 → 10 dégâts d''acide selon le niveau (+1 si la cible porte une armure) ; à haut niveau, peut frapper 2 cibles.' WHERE nom = 'Toucher Corrosif' AND cercle = 'Terre';
UPDATE public.sorts SET description_courte = 'Zone d''acide : 1 → 4 dégâts selon le niveau, répétés chaque minute (+1 contre armure physique, qu''elle finit par détruire). Niv. 20 : alliés épargnés.' WHERE nom = 'Pluie acide' AND cercle = 'Terre';
